import React, { PropsWithChildren, ReactNode } from 'react';

import { Group } from './components/Group.js';
import { Item } from './components/Item.js';
import { ItemIcon } from './components/ItemIcon.js';
import { ItemTooltip } from './components/ItemTooltip.js';
import { Label } from './components/Label.js';
import { AriaLabelingProps } from '../../../../core/types/a11y-props.js';
import { DOMProps } from '../../../../core/types/dom.js';

export type ChartSeriesActionProps = DOMProps &
  AriaLabelingProps & {
    children: ReactNode;
    /**
     * Disabled
     * @defaultValue false
     */
    disabled?: boolean;
  };

/**
 * ChartSeriesAction component
 */
const _ChartSeriesAction = ({
  children,
}: PropsWithChildren<ChartSeriesActionProps>) => (
  // eslint-disable-next-line react/jsx-no-useless-fragment
  <>{children}</>
);

_ChartSeriesAction['displayName'] = 'ChartSeriesAction';

/** Slot component for chart series actions */
export const ChartSeriesAction = Object.assign(_ChartSeriesAction, {
  Item,
  ItemTooltip,
  Label,
  ItemIcon,
  Group,
});
